{
  "name": "@dzhechkov/adapter-opencode",
  "version": "0.2.9",
  "description": "OpenCode platform adapter - compiles canonical skills into the .opencode/skills tree.",
  "type": "module",
  "license": "MIT",
  "author": "dzhechko",
  "keywords": [
    "agent-skills",
    "opencode",
    "adapter",
    "harness"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "src",
    "README.md",
    ".dz-manifest.json",
    "sbom.json"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "vitest run",
    "test:watch": "vitest",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "lint": "tsc -p tsconfig.json --noEmit"
  },
  "dependencies": {
    "@dzhechkov/core": "0.2.30"
  },
  "devDependencies": {
    "@types/node": "^25.6.0",
    "typescript": "^5.7.0",
    "vitest": "^3.0.0",
    "yaml": "^2.0.0"
  },
  "engines": {
    "node": ">=20"
  },
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/djd1m/dz-harness.git",
    "directory": "packages/@dzhechkov/adapter-opencode"
  },
  "homepage": "https://aicoding.space",
  "bugs": {
    "url": "https://github.com/djd1m/dz-harness/issues"
  }
}
